# --- your code ---
def convert(facts: list[list], queries: list[list[str]]) -> list[float]:
    graph = {}
    for a, b, k in facts:
        graph.setdefault(a, []).append((b, k))
        graph.setdefault(b, []).append((a, 1 / k))
    answers = []
    for x, y in queries:                          # a fresh search for every query
        found, seen, stack = -1.0, {x}, [(x, 1.0)]
        while stack and x in graph:
            unit, amount = stack.pop()            # one x = amount units
            if unit == y:
                found = amount
                break
            for nxt, k in graph[unit]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append((nxt, amount * k))
        answers.append(found)
    return answers


